// Which build am I looking at? config.js (generated by build.sh) carries the
// short commit and the build time; without it — local dev, or an unbuilt
// checkout — say so instead of showing a blank.

const REPO_URL = 'https://github.com/sebastianzillessen/experiments';

export function AppVersion() {
  const version = window.__APP_VERSION;
  const commit = version?.commit;
  const builtAt = version?.builtAt;

  if (!commit || commit === 'unknown') {
    return <span className="app-version">Entwicklungsversion</span>;
  }

  return (
    <span className="app-version">
      <a href={`${REPO_URL}/commit/${commit}`} target="_blank" rel="noreferrer"
        title="Diesen Stand auf GitHub ansehen">{commit}</a>
      {builtAt && <> · {builtAt}</>}
    </span>
  );
}
